breaking_changes.Adaptation_method:
Before:
const {stdout} = await execa('node', ['file.js'], {encoding: 'buffer'});
console.log(Buffer.isBuffer(stdout)); // true

After:
const {stdout} = await execa('node', ['file.js'], {encoding: 'buffer'});
console.log(stdout instanceof Uint8Array); // true
// If Buffer is needed:
const buffer = Buffer.from(stdout);

Note: The same applies to execaSync(). Also, remove any use of 'encoding: null', as it is no longer supported.

Update any execa and execaSync calls as follows:
// Before:
await execa('node', ['file.js'], {encoding: null});
await execa('node', ['file.js'], {encoding: 'utf-8'});
await execa('node', ['file.js'], {encoding: 'binary'});
const {stdout} = await execa('node', ['file.js'], {encoding: 'buffer'}); // stdout is a Buffer

// After:
await execa('node', ['file.js'], {encoding: 'buffer'}); // null is invalid
await execa('node', ['file.js'], {encoding: 'utf8'});
await execa('node', ['file.js'], {encoding: 'latin1'});
const {stdout} = await execa('node', ['file.js'], {encoding: 'buffer'}); // stdout is a Uint8Array

If your code expects 'Buffer', update type assertions and conversion as necessary for 'Uint8Array'.

// Writing stdout or stderr to a file:
// Before:
await execa('node', ['file.js']).pipeStdout('output.txt');
// After:
await execa('node', ['file.js'], {stdout: {file: 'output.txt'}});

// Writing stdout or stderr to a writable stream:
// Before:
await execa('node', ['file.js']).pipeStdout(stream);
// After:
await execa('node', ['file.js'], {stdout: ['pipe', stream]});

// Before:
await execa('node', ['file.js']).pipeStdout(execa('node', ['other.js']));
// After:
await execa('node', ['file.js']).pipe('node', ['other.js']);

// Before:
await execa('node', ['file.js']).pipeStderr(execa('node', ['other.js']));
// After:
await execa('node', ['file.js']).pipe('node', ['other.js'], {from: 'stderr'});

// Before:
await execa('node', ['file.js']).pipeAll(execa('node', ['other.js']));
// After:
await execa('node', ['file.js']).pipe('node', ['other.js'], {from: 'all'});

// Before:
await execa('node', ['file.js'], {signal: abortController.signal});
// After:
await execa('node', ['file.js'], {cancelSignal: abortController.signal});

// Before:
subprocess.cancel();
// After:
subprocess.kill();
// Alternatively, use the cancelSignal option when supported.

// Before:
const subprocess = execa('node', ['file.js']);
subprocess.kill('SIGTERM', {forceKillAfterTimeout: 1000});
// After:
const subprocess = execa('node', ['file.js'], {forceKillAfterDelay: 1000});
subprocess.kill('SIGTERM');

// Before:
await execa('node', ['file.js'], {verbose: false}); // or true
// After:
await execa('node', ['file.js'], {verbose: 'none'}); // or 'short'

// Before:
await execa('node', ['file.js'], {execPath: './path/to/node'});
// After:
await execa('node', ['file.js'], {nodePath: './path/to/node'});

Do not pass objects with functions or symbols to subprocess.send().
// Before:
subprocess.send({example: true, getExample() {}});
// After:
subprocess.send({example: true});

If you need to send functions or symbols, you must refactor your code so those properties are excluded before sending, or handle them separately. Alternatively, explicitly pass 'serialization: "json"' as an option to revert to the old behavior:
subprocess.send(obj, {serialization: 'json'});

// Before:
const subprocess = execa('node', ['file.js']);
setTimeout(() => subprocess.stdout.pipe(process.stdout), 0);
// After:
const subprocess = execa('node', ['file.js']);
subprocess.stdout.pipe(process.stdout);

// Before:
const subprocess = execa('node', ['file.js'], {killSignal: 'sigterm'});
subprocess.kill('sigterm');
// After:
const subprocess = execa('node', ['file.js'], {killSignal: 'SIGTERM'});
subprocess.kill('SIGTERM');
